from pathlib import Path
import base64,hashlib,json,subprocess,zipfile
W=Path('/kaggle/working/hp_round14');P=Path('/root/hp_round14_pulls');P.mkdir(exist_ok=True)
# Restore immutable inputs from durable bundles, without re-encoding or rerunning.
with zipfile.ZipFile(W/'completed_compact_v1.zip') as z:
    rows=json.loads(z.read('entries.json'))
    for r in rows:
        if '/warm-' in r['path'] and r['path'].endswith('manifest.json'):
            data=z.read(r['path']);assert hashlib.sha256(data).hexdigest()==r['sha256']
            p=(P/r['path']).resolve();assert p.is_relative_to(P);p.parent.mkdir(parents=True,exist_ok=True);p.write_bytes(data)
for role in ('development','confirmation'):
    target=P/f'hutter-r13-warm-{role}-v1'/('warm-'+role)
    with zipfile.ZipFile(W/('warm_costs_'+role+'.zip')) as z:
        for r in json.loads(z.read('entries.json')):
            data=z.read(r['path']);assert hashlib.sha256(data).hexdigest()==r['sha256'];(target/r['path']).write_bytes(data)
    m=json.loads((target/'manifest.json').read_text())
    assert len(m['cases'])==8
    for row in m['cases']:
        assert set(('id','offset','bytes','warmup_bytes'))<=row['region'].keys()
        assert row['region']['bytes']==3145728 and row['independent_decode_exact']
Path('/root/r14_collect_batch.py').write_bytes(base64.b64decode(''))
Path('/root/r14_word_cost_v2.py').write_bytes(base64.b64decode(''))
Path('/root/research_round14_word_events.cpp').write_bytes(base64.b64decode(''))
assert not (W/'batch_collection_v1.json').exists() and not (W/'word_costs_v2').exists()
pids={}
for name,path in [('batch_collection','/root/r14_collect_batch.py'),('word_costs_v2','/root/r14_word_cost_v2.py')]:
    p=subprocess.Popen(['python',path],stdin=subprocess.DEVNULL,stdout=(W/(name+'.log')).open('ab'),stderr=subprocess.STDOUT,start_new_session=True);pids[name]=p.pid
print(json.dumps(pids))